arguments.argument:
shakable = (shakable + 1) mod 5;

if( shakable )
    global.farting_time = 3;

switch( shakable ){
  case 0:
    draw_text_on_board("No Shaking", true);
    break;

  case 1:
    draw_text_on_board("Shake (Vertical)", true);
    break;

  case 2:
    draw_text_on_board("Shake (Horizontal)", true);
    break;

  case 3:
    draw_text_on_board("Shake (Zoom)", true);
    break;

  case 4:
    draw_text_on_board("Shake (Random)", true);
    break;

}
